    {
      "id": 5,
      "objective": "Search for remote/cloud lab design-print-test systems and their measured outcomes",
      "rationale": "Core of question 5 - need completion rates, turnaround, interventions",
      "status": "pending",
      "result": null,
      "evaluation": null
    },
    {
      "id": 6,
      "objective": "Search for adhesion forces of PLA/PETG on PEI, sheet flexing forces, and grasping of irregular printed parts",
